app_css:
.tool-app-milelog { color: #0f3f3a; max-width: 900px; margin-inline: auto; }
.tool-app-milelog .ml-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; margin: 12px 0; }
.tool-app-milelog .ml-stat { background: #f0fdfa; border: 1px solid #99f6e4; border-radius: 10px; padding: 10px 14px; display: flex; flex-direction: column; gap: 2px; }
.tool-app-milelog .ml-stat span { font-size: 12px; color: #0f766e; font-weight: 600; }
.tool-app-milelog .ml-stat strong { font-size: 22px; color: #0f3f3a; }
.tool-app-milelog .ml-row { display: flex; gap: 12px; margin: 12px 0; flex-wrap: wrap; align-items: end; }
.tool-app-milelog .ml-form { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px; margin: 12px 0; align-items: end; }
.tool-app-milelog label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-milelog input[type="text"], .tool-app-milelog input[type="number"], .tool-app-milelog input[type="date"], .tool-app-milelog select { border: 1px solid #99f6e4; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; }
.tool-app-milelog .ml-btn { background: #0D9488; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-milelog .ml-btn:hover { background: #0f766e; }
.tool-app-milelog .ml-btn-ghost { background: #f0fdfa; color: #0D9488; }
.tool-app-milelog .ml-btn-ghost:hover { background: #ccfbf1; }
.tool-app-milelog .ml-btn-danger { background: #fef2f2; color: #b91c1c; }
.tool-app-milelog .ml-btn-danger:hover { background: #fee2e2; }
.tool-app-milelog .ml-table { width: 100%; border-collapse: collapse; margin: 12px 0; }
.tool-app-milelog .ml-table th { text-align: left; font-size: 12px; color: #0f766e; padding: 6px; }
.tool-app-milelog .ml-table td { padding: 6px; border-top: 1px solid #ccfbf1; font-size: 14px; }
.tool-app-milelog .ml-table td.ml-miles, .tool-app-milelog .ml-table td.ml-ded { white-space: nowrap; font-weight: 600; }
.tool-app-milelog .ml-remove { background: none; border: none; color: #b91c1c; font-size: 20px; cursor: pointer; }
.tool-app-milelog .ml-actions { display: flex; gap: 10px; margin: 14px 0; flex-wrap: wrap; }
.tool-app-milelog .tool-print-doc { display: none; }
@media print {
  .tool-app-milelog .ml-screen { display: none !important; }
  .tool-app-milelog .tool-print-doc { display: block !important; color: #000; }
  .tool-app-milelog .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-milelog .tool-print-doc th, .tool-app-milelog .tool-print-doc td { border: 1px solid #999; padding: 6px; text-align: left; font-size: 13px; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  function miles(n) { n = parseFloat(n); return (isFinite(n) ? n : 0).toFixed(1) + ' mi'; }
  var root = $('toolAppRoot');
  var LS_TRIPS = 'toolapp-milelog-trips';
  var LS_RATE = 'toolapp-milelog-rate';
  function getTrips() {
    try { return JSON.parse(localStorage.getItem(LS_TRIPS)) || []; } catch (e) { return []; }
  }
  function setTrips(t) {
    try { localStorage.setItem(LS_TRIPS, JSON.stringify(t)); } catch (e) {}
  }
  function getRate() {
    var r = parseFloat($('ml-rate').value);
    if (!isFinite(r) || r < 0) r = 0;
    return r;
  }
  function saveRate() {
    try { localStorage.setItem(LS_RATE, String(getRate())); } catch (e) {}
  }
  function monthKey(d) { return d.slice(0, 7); }
  function monthLabel(d) {
    var parts = d.split('-');
    var names = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return names[parseInt(parts[1], 10) - 1] + ' ' + parts[0];
  }
  function tripMiles(t) {
    if (t.odoStart != null && t.odoStart !== '' && t.odoEnd != null && t.odoEnd !== '') {
      var m = parseFloat(t.odoEnd) - parseFloat(t.odoStart);
      return m > 0 ? m : 0;
    }
    return parseFloat(t.manual) || 0;
  }
  function refreshMonths() {
    var sel = $('ml-month');
    var cur = sel.value || 'all';
    var keys = {};
    getTrips().forEach(function (t) { if (t.date) keys[monthKey(t.date)] = true; });
    var list = Object.keys(keys).sort().reverse();
    sel.innerHTML = '';
    var all = document.createElement('option');
    all.value = 'all'; all.textContent = 'All time';
    sel.appendChild(all);
    list.forEach(function (k) {
      var o = document.createElement('option');
      o.value = k; o.textContent = monthLabel(k + '-01');
      sel.appendChild(o);
    });
    var found = false;
    for (var i = 0; i < sel.options.length; i++) {
      if (sel.options[i].value === cur) { found = true; break; }
    }
    sel.value = found ? cur : 'all';
  }
  function render() {
    var rate = getRate();
    var sel = $('ml-month').value || 'all';
    var all = getTrips().slice().sort(function (a, b) { return (b.date || '').localeCompare(a.date || ''); });
    var trips = all.filter(function (t) { return sel === 'all' || (t.date && monthKey(t.date) === sel); });
    var tb = $('ml-trips');
    tb.innerHTML = '';
    var totalMiles = 0;
    trips.forEach(function (t, idx) {
      var m = tripMiles(t);
      totalMiles += m;
      var tr = document.createElement('tr');
      var route = [t.from, t.to].filter(function (x) { return x; }).join(' \u2192 ');
      tr.innerHTML =
        '<td>' + esc(t.date || '') + '</td>' +
        '<td>' + esc(t.purpose || '') + '</td>' +
        '<td>' + esc(route) + '</td>' +
        '<td class="ml-miles">' + m.toFixed(1) + '</td>' +
        '<td class="ml-ded">' + money(m * rate) + '</td>' +
        '<td><button type="button" class="ml-remove" data-date="' + esc(t.date || '') + '" data-ts="' + t.ts + '" aria-label="Delete trip">\u00d7</button></td>';
      tb.appendChild(tr);
    });
    if (!trips.length) {
      var tr0 = document.createElement('tr');
      var td0 = document.createElement('td');
      td0.colSpan = 6;
      td0.textContent = 'No trips logged yet. Add your first trip above.';
      tr0.appendChild(td0);
      tb.appendChild(tr0);
    }
    $('ml-total-miles').textContent = totalMiles.toFixed(1);
    $('ml-total-ded').textContent = money(totalMiles * rate);
    $('ml-total-trips').textContent = String(trips.length);
    var nowMonth = new Date().toISOString().slice(0, 7);
    var mm = 0;
    all.forEach(function (t) { if (t.date && monthKey(t.date) === nowMonth) mm += tripMiles(t); });
    $('ml-month-miles').textContent = mm.toFixed(1) + ' mi';
    renderPrintDoc(trips, totalMiles, rate);
  }
  function renderPrintDoc(trips, totalMiles, rate) {
    var rows = '';
    trips.forEach(function (t) {
      var m = tripMiles(t);
      var route = [t.from, t.to].filter(function (x) { return x; }).join(' - ');
      rows += '<tr><td>' + esc(t.date || '') + '</td><td>' + esc(t.purpose || '') + '</td>' +
        '<td>' + esc(route) + '</td><td>' + m.toFixed(1) + '</td><td>' + money(m * rate) + '</td></tr>';
    });
    $('ml-printdoc').innerHTML =
      '<h1>Mileage Log Report</h1>' +
      '<p><strong>Period:</strong> ' + esc(($('ml-month').selectedOptions[0] || {}).textContent || 'All time') + '<br>' +
      '<strong>Rate:</strong> ' + money(rate) + ' per mile<br>' +
      '<strong>Total trips:</strong> ' + trips.length + '<br>' +
      '<strong>Total miles:</strong> ' + totalMiles.toFixed(1) + '<br>' +
      '<strong>Total deduction:</strong> ' + money(totalMiles * rate) + '</p>' +
      '<table><thead><tr><th>Date</th><th>Purpose</th><th>Route</th><th>Miles</th><th>Deduction</th></tr></thead>' +
      '<tbody>' + rows + '</tbody></table>' +
      '<p>Signature: ____________________________________ &nbsp;&nbsp; Date: ____________</p>';
  }
  function addTrip() {
    var date = $('ml-date').value;
    var purpose = $('ml-purpose').value.trim();
    var odoStart = $('ml-odo-start').value;
    var odoEnd = $('ml-odo-end').value;
    var manual = parseFloat($('ml-miles').value) || 0;
    if (!date) { alert('Pick a date for the trip.'); return; }
    if (!purpose) { alert('Enter the business purpose (the IRS requires it).'); return; }
    if (odoStart !== '' && odoEnd !== '' && parseFloat(odoEnd) < parseFloat(odoStart)) {
      alert('End odometer must be greater than start odometer.');
      return;
    }
    if ((odoStart === '' || odoEnd === '') && manual <= 0) {
      alert('Enter odometer readings or the miles driven.');
      return;
    }
    var trips = getTrips();
    trips.push({
      ts: Date.now(),
      date: date,
      purpose: purpose,
      from: $('ml-from').value.trim(),
      to: $('ml-to').value.trim(),
      odoStart: odoStart, odoEnd: odoEnd, manual: manual
    });
    setTrips(trips);
    $('ml-purpose').value = '';
    $('ml-from').value = '';
    $('ml-to').value = '';
    $('ml-odo-start').value = '';
    $('ml-odo-end').value = '';
    $('ml-miles').value = '';
    refreshMonths();
    render();
  }
  function exportCsv() {
    var trips = getTrips().slice().sort(function (a, b) { return (a.date || '').localeCompare(b.date || ''); });
    var rate = getRate();
    var lines = ['Date,Purpose,From,To,Start odometer,End odometer,Miles,Deduction'];
    trips.forEach(function (t) {
      var m = tripMiles(t);
      function q(v) { return '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"'; }
      lines.push([t.date, q(t.purpose), q(t.from), q(t.to), t.odoStart, t.odoEnd, m.toFixed(1), money(m * rate)].join(','));
    });
    var blob = new Blob([lines.join('\r\n')], { type: 'text/csv' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'mileage-log.csv';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 100);
  }
  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'ml-add') { addTrip(); return; }
    if (t.id === 'ml-export') { exportCsv(); return; }
    if (t.id === 'ml-print') { render(); window.print(); return; }
    if (t.id === 'ml-clear') {
      if (confirm('Delete ALL logged trips? This cannot be undone.')) {
        setTrips([]);
        refreshMonths();
        render();
      }
      return;
    }
    if (t.classList && t.classList.contains('ml-remove')) {
      var ts = parseInt(t.getAttribute('data-ts'), 10);
      var trips = getTrips().filter(function (x) { return x.ts !== ts; });
      setTrips(trips);
      refreshMonths();
      render();
    }
  });
  $('ml-rate').addEventListener('change', function () { saveRate(); render(); });
  $('ml-month').addEventListener('change', render);
  (function init() {
    var saved = null;
    try { saved = localStorage.getItem(LS_RATE); } catch (e) {}
    if (saved != null && saved !== '') $('ml-rate').value = saved;
    $('ml-date').value = new Date().toISOString().slice(0, 10);
    refreshMonths();
    render();
  })();
})();
